<?php require 'config/database.php';$schools=$pdo->query('SELECT id,name FROM schools ORDER BY name')->fetchAll();$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){$q=$pdo->prepare('INSERT INTO services(school_id,service_type,subject,description,requester,phone) VALUES(?,?,?,?,?,?)');$q->execute([$_POST['school_id']?:null,trim($_POST['service_type']),trim($_POST['subject']),trim($_POST['description']),trim($_POST['requester']),trim($_POST['phone'])]);$ok='Permohonan berhasil dikirim.';}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Layanan Bidang SMP</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="top"><b>Layanan Bidang SMP</b><a style="color:#fff" href="index.php">Beranda</a></div><div class="container"><div class="panel"><h1>Permohonan Layanan</h1><?php if($ok):?><div class="notice"><?=e($ok)?></div><?php endif;?><form method="post"><div class="grid"><div><label>Sekolah</label><select name="school_id"><option value="">-- Pilih --</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><div><label>Jenis Layanan</label><input class="input" name="service_type" required></div><div><label>Nama Pemohon</label><input class="input" name="requester" required></div><div><label>No. HP</label><input class="input" name="phone" required></div><div><label>Subjek</label><input class="input" name="subject" required></div></div><label>Uraian</label><textarea name="description" rows="6" required></textarea><button class="btn">Kirim Permohonan</button></form></div></div></body></html>
